  D=[cx("Calcula (1/2 + 1/3) ÷ (1/2 − 1/3).", "(F(1,2)+F(1,3))/(F(1,2)-F(1,3))", "El numerador vale 5/6 y el denominador vale 1/6."),
     cx("Halla x en x + 3/4 = (−1/2)·(−5/2).", "F(-1,2)*F(-5,2)-F(3,4)", "El producto vale 5/4; se resta 3/4 a ambos lados.")],
